  applyIntervalView(historyComplete=false){const intent=this.pendingIntervalView;if(!intent||intent.navigation===undefined||intent.key!==this.datasetKey()||!this.usable())return;if(intent.navigation!==this.navigationTicket){this.pendingIntervalView=null;return;}const futureReady=intent.preferFuture&&this.candidates?.current();if(futureReady)this.fitCandidateRange();else{const index=this.indexForDate(intent.at);this.count=Math.min(PERIODS[this.interval()].count,this.totalSlots());if(index!==undefined){this.start=clamp(index-Math.floor(this.count*.65),0,Math.max(0,this.totalSlots()-this.count));this.inspect(index,true);}}if((!intent.preferFuture||futureReady)&&(historyComplete||!this.loading))this.pendingIntervalView=null;this.render();}
